var datum, txt;

// Beschreibe diese Funktion …
async function Logfile(datum, txt) {
    if (getState('0_userdata.0.go-e.DebugAktiv').val) {
      require('fs').appendFileSync('/opt/iobroker/log/' + datum + ' - Cupra.log', formatDate(new Date(), "hh:mm:ss") + " \t" + txt + "\n");}
}


// ------->>>> Logfile

// ------->>> Error
on({ id: [].concat(['mqtt.0.go-eCharger.069113.err']), change: 'ne' }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  if (getState('mqtt.0.go-eCharger.069113.err').val > 0) {
    console.warn(('go-e / Error: ' + String(getState('mqtt.0.go-eCharger.069113.err').val)));
    sendTo('telegram.0', 'send', {
      text: ('go-e / Error: ' + String(getState('mqtt.0.go-eCharger.069113.err').val)),
    });
    console.error('telegram: ' + ('go-e / Error: ' + String(getState('mqtt.0.go-eCharger.069113.err').val)));
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'ERROR: ' + String(getState('mqtt.0.go-eCharger.069113.err').val));
    setState('mqtt.0.go-eCharger.069113.alw', false);
  }
});


